scwin.clickBzProcsNo = "";
scwin.vScrenID = "ULDBNS25500.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 설명       : 일자 조회
 ***********************************************/
scwin.fn_getDate = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=ULDSTF41001_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.elwko.select.getPrevBusiDt";
    dts_getDate.DataID = encodeURI(url);
    dts_getDate.reset();
};


/********************************************** 
 * 설명       : 조회
 ***********************************************/
scwin.fn_Search = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();

    // 지표종목별
    if (vsTabSel == "1") {
        scwin.fn_Search1();
        // 발행만기별

    } else if (vsTabSel == "2") {
        scwin.fn_Search2();
        // 잔존만기별

    } else if (vsTabSel == "3") {
        scwin.fn_Search3();
        // 개별종목별

    } else if (vsTabSel == "4") {
        scwin.fn_Search4();
    }
};



/********************************************** 
 * 설명       : 지표종목별
 ***********************************************/
scwin.fn_Search1 = function() {
    var vsRdbValue = $c.stf.getObjectValue(rdo_Ji_Trem);
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_TRESRY_BND_LIST_VAL_JI_LIST";
    if (vsRdbValue == "D") {
        url += "&queryId=lds.stf.bnstresry_bnd_list_bal.select.listjiday";
    } else if (vsRdbValue == "M") {
        url += "&queryId=lds.stf.bnstresry_bnd_list_bal.select.listjimon";
    } else if (vsRdbValue == "Y") {
        url += "&queryId=lds.stf.bnstresry_bnd_list_bal.select.listjiyear";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_Ji_SDate);
    url += "&{P}V_END_DD=" + $c.stf.getObjectValue(edt_Ji_EDate);
    dts_List1.DataID = encodeURI(url);
    dts_List1.Reset();
    $c.cm.ShowWin(grd_List1);
};


/********************************************** 
 * 설명       : 발행만기별
 ***********************************************/
scwin.fn_Search2 = function() {
    var vsRdbValue = $c.stf.getObjectValue(rdo_Ba_Trem);
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_TRESRY_BND_LIST_VAL_BA_LIST";
    if (vsRdbValue == "D") {
        url += "&queryId=lds.stf.bnstresry_bnd_list_bal.select.listbaday";
    } else if (vsRdbValue == "M") {
        url += "&queryId=lds.stf.bnstresry_bnd_list_bal.select.listbamon";
    } else if (vsRdbValue == "Y") {
        url += "&queryId=lds.stf.bnstresry_bnd_list_bal.select.listbayear";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_Ba_SDate);
    url += "&{P}V_END_DD=" + $c.stf.getObjectValue(edt_Ba_EDate);
    dts_List2.DataID = encodeURI(url);
    dts_List2.Reset();
    $c.cm.ShowWin(grd_List2);
};


/********************************************** 
 * 설명       : 잔존만기별
 ***********************************************/
