    } else if (vs_Ja_Gb == "L") {
        url += "&queryId=lds.stf.bnstresry_bnd_list_bal.select.listjal";
    }
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_STRT_DD=" + $c.stf.getObjectValue(edt_Ja_SDate);
    url += "&{P}V_END_DD=" + $c.stf.getObjectValue(edt_Ja_EDate);
    url += "&{P}V_TERM_TP_CD=" + $c.stf.getObjectValue(rdo_Ja_Trem);
    dts_List3.DataID = encodeURI(url);
