};


/********************************************** 
 * 설명       : 개별종목별
 ***********************************************/
scwin.fn_Search4 = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_TRESRY_BND_LIST_VAL_PL_LIST";
    url += "&queryId=lds.stf.bnstresry_bnd_list_bal.select.listpl";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}V_STD_DT=" + $c.stf.getObjectValue(edt_Pl_SDate);
    url += "&{P}V_TYPE=" + $c.stf.getObjectValue(cmb_Type);
    url += "&{P}V_BND_STRIP_TP_CD=" + $c.stf.getObjectValue(cmb_BndStripTpCd);
    dts_List4.DataID = encodeURI(url);
    dts_List4.Reset();
    $c.cm.ShowWin(grd_List4);
};


/********************************************** 
 * 설명       : 정보를 excel로 다운 받는다.
 ***********************************************/
scwin.fn_ExcelDown = function() {
    var vsTabSel = tab_Main.getSelectedTabIndex();
    var voDtsList = null;
    var voGrid = null;
    var excelSheet = '';

    // 전체조회
    if (vsTabSel == "1") {
        excelSheet = '지표종목별';
        voDtsList = dts_List1;
        voGrid = grd_List1;
        // 개별종목조회

    } else if (vsTabSel == "2") {
        excelSheet = '발행만기별';
        voDtsList = dts_List2;
        voGrid = grd_List2;
        // 일괄상장종목조회

    } else if (vsTabSel == "3") {
        excelSheet = '잔존만기별';
        voDtsList = dts_List3;
        voGrid = grd_List3;
        // 일괄상장종목조회

    } else if (vsTabSel == "4") {
        excelSheet = '개별종목별';
        voDtsList = dts_List4;
        voGrid = grd_List4;
    }
    if (voDtsList.getTotalRow() > 0) {
        //엑셀 로그 
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_국고채권 상장잔액.xls";
        voGrid.GridToExcel(excelSheet, "", "8");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.gform_onload = function() {
    /********************************************** 
     * 함수명   : gform > onload
     * 설명      : 화면 Onload
     ***********************************************/
    tab_Main.setSelectedTabIndex(1);
    $c.bns.BnsPanelToGroupBox(panel_Top_1);
    $c.bns.BnsPanelToGroupBox(panel_Top_2);
    $c.bns.BnsPanelToGroupBox(panel_Top_3);
    $c.bns.BnsPanelToGroupBox(panel_Top_4);

    //fn_initSearchDate(edt_SDate, edt_EDate);                       // 신청일 기간

    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    scwin.fn_getDate();
    $c.stf.setObjectValue(edt_Ji_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    $c.stf.setObjectValue(edt_Ji_EDate, dts_getDate.getCellData(3, "CALND_DD"));
    $c.stf.setObjectValue(edt_Ba_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    $c.stf.setObjectValue(edt_Ba_EDate, dts_getDate.getCellData(3, "CALND_DD"));
    $c.stf.setObjectValue(edt_Ja_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    $c.stf.setObjectValue(edt_Ja_EDate, dts_getDate.getCellData(3, "CALND_DD"));
    $c.stf.setObjectValue(edt_Pl_SDate, dts_getDate.getCellData(3, "CALND_DD"));
    edt_Ji_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    edt_Ji_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    edt_Ba_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    edt_Ba_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    edt_Ja_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    edt_Ja_EDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));
    edt_Pl_SDate.setValue($c.ut.cGetMinusDate2($c.ut.cGetToday("yyyymmdd"), 0));



    //fn_list_sync();

};
scwin.btn_Search_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Search > onclick
     * 설명      : 조회버튼 클릭
     ***********************************************/
    if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        scwin.fn_Search();
    }
};
