scwin.btn_Excel_onclick = function() {
    /********************************************** 
     * 함수명   : btn_Excel > onclick
     * 설명      : 엑셀버튼 클릭
     ***********************************************/
    scwin.fn_ExcelDown();
};
scwin.btn_Close_onclick = async function() {
    /********************************************** 
     * 함수명   : btn_Close > onclick
     * 설명      : 닫기버튼 클릭
     ***********************************************/
    await $c.frame.CloseFrame();
};
scwin.dts_List1_OnLoadError = function() {
    /********************************************** 
     * 함수명   : dts_List1 > OnLoadError
     * 설명      : dts_List1 조회 에러 
     ***********************************************/
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List1_OnLoadCompleted = function(rowcount) {
    /********************************************** 
     * 함수명   : dts_List1 > OnLoadError
     * 설명      : dts_List1 조회 성공
     ***********************************************/
